/** Generated from the overhaul textbook. Re-run tools/import-overhaul-courses.mjs. Do not edit by hand. */
export default {"id":"note-level-14","number":14,"title":"Export Live Capstone","skillBand":"Textbook","duration":"From the course textbook","summary":"11.1","modules":[{"id":"note-m-11-1-101","code":"11.1","title":"11.1","blurb":"11.1","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l11-1-1","title":"11.1.1 — Set Settings → Export Audio","blocks":[{"type":"step","title":"11.1.1 — Set Settings → Export Audio","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.1 — Export audio</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can open <strong>Export Audio</strong> from <strong>Set Settings</strong> and say what the bounce contains."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"You export an audio WAV or M4A of the Set directly from Note and save it to Files or share it with AirDrop or other apps. The door is <strong>Set Settings</strong>, the icon at the top right of an open Set — the same menu as tempo, metronome, Key &amp; Scale, and Groove Amount. Select <strong>Export Audio</strong> to reach the export settings."},{"type":"prose","html":"The file is an ordered sequence of all scenes from top to bottom. The longest clip in each scene sets that scene’s length in the recording. This is not Cloud (a Set folder in Live’s browser) and not <strong>Share To…</strong> (an <code>.ablbundle</code>). It is a stereo bounce of the Session grid in scene order."},{"type":"prose","html":"If the Set has no clips, <strong>Export Audio</strong> is greyed out (next lesson). Put at least one clip in the Set before you hunt for a missing button."},{"type":"prose","html":"Use this when someone needs to hear the idea and does not need to open Note or Live."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Open a Set that already has clips.","Tap <strong>Set Settings</strong> (top right).","Tap <strong>Export Audio</strong>. Do not tap Cloud or <strong>Share To…</strong>.","Read that you are about to pick a format (11.1.3). You may cancel after you have seen the door.","Close <strong>Set Settings</strong> and open <strong>Export Audio</strong> again from memory.","Write: scenes top to bottom; longest clip sets each scene’s length."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Where is <strong>Export Audio</strong>? <strong>Answer:</strong> <strong>Set Settings</strong> (top right of the open Set).","What order does the bounce use? <strong>Answer:</strong> All scenes, top to bottom. Longest clip in a scene sets that scene’s length.","Is this the same as uploading to Cloud? <strong>Answer:</strong> No. Export is a WAV or M4A. Cloud transfers the Set."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §5.4 and §10.2","Ableton Note.md §5.2 Exporting as an Audio File","Note FAQ p.1 (export audio directly)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Open <strong>Export Audio</strong> on a Set that has clips. Screenshot the <strong>Set Settings</strong> row so you can find it cold."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-1-1</code></em>"}]}],"minutes":8},{"id":"note-l11-1-2","title":"11.1.2 — Greyed with no clips","blocks":[{"type":"step","title":"11.1.2 — Greyed with no clips","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.1 — Export audio</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can predict that <strong>Export Audio</strong> is greyed out until the Set contains at least one clip."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"If no clips are present in the Set, the <strong>Export Audio</strong> option is greyed out. That is Manual §5.4 in one sentence. An empty Session — tracks with presets but no captured or added clips — has nothing to render. Scenes top to bottom of silence is not an export."},{"type":"prose","html":"Create a clip the way you already do: <strong>Add Clip</strong> then play (Fixed Length), or play and tap <strong>Capture</strong> (Free Length). One one-bar loop is enough to un-grey the command. You do not need eight tracks or a Cloud upload."},{"type":"prose","html":"This is a useful fail: if export is grey, you are not in the wrong menu. You are in a Set with no clips. Demo Sets have clips; your new <strong>+ New</strong> Set may not."},{"type":"prose","html":"Gate J requires an audio export. That requirement implies clips exist. Do not fight a grey button on an empty sketch."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Create a <strong>+ New</strong> Set or duplicate a Set and delete its clips until none remain (use a disposable duplicate).","Open <strong>Set Settings</strong>. Confirm <strong>Export Audio</strong> is greyed.","Add one clip via <strong>Add Clip</strong> or <strong>Capture</strong>.","Open <strong>Set Settings</strong> again. Confirm <strong>Export Audio</strong> is available.","Delete that clip (if you want) and watch it grey again. Restore a clip before you leave.","Repeat from memory on any Set you plan to bounce."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["When is <strong>Export Audio</strong> greyed out? <strong>Answer:</strong> When no clips are present in the Set.","What is the smallest fix? <strong>Answer:</strong> Create at least one clip (Capture or Add Clip).","Does greying mean Export moved to Cloud? <strong>Answer:</strong> No. The command stays in <strong>Set Settings</strong>."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §5.4","Ableton Note Manual §10.2","Capture in Note (how clips appear)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Prove the grey/active pair on a disposable Set. Leave that Set with one clip so 11.1.3 can export it."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-1-2</code></em>"}]}],"minutes":8},{"id":"note-l11-1-3","title":"11.1.3 — Export settings UI","blocks":[{"type":"step","title":"11.1.3 — Export settings UI","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.1 — Export audio</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can choose WAV or M4A at the official sample rates and bit depths, then start the render."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Inside <strong>Export Audio</strong> you choose the file type, then press <strong>Export</strong>. The two official formats: uncompressed WAV at 48 kHz, 16-bit, or compressed M4A at 48 kHz, 32-bit. Pick one. There is no MP3 export in these pages (Note can <em>import</em> MP3/M4A as samples and convert them to WAV; that is inbound, not this bounce)."},{"type":"prose","html":"After you press <strong>Export</strong>, Note shows a progress bar. When the render finishes, an audio preview of the finished recording appears. From there you <strong>Share</strong> or <strong>Cancel</strong>. <strong>Cancel</strong> leaves the preview and returns you to Session View. It does not invent a project file."},{"type":"prose","html":"WAV is the interchange bounce for a DAW or a collaborator who will transcode later. M4A is the smaller share. Both are 48 kHz. Do not invent 44.1 kHz or 24-bit WAV as a Note export option."},{"type":"prose","html":"The bounce still follows scene order and longest-clip scene lengths. Arranging scenes <em>before</em> you open this UI is the musical work (11.1.7)."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Open a Set with clips. Tap <strong>Set Settings → Export Audio</strong>.","Read the two format choices. Write WAV 48 kHz 16-bit and M4A 48 kHz 32-bit.","Select WAV for this pass (or M4A if you need a small file).","Press <strong>Export</strong>. Watch the progress bar.","When the preview appears, listen. Do not <strong>Share</strong> yet if you only wanted the UI (or <strong>Share</strong> to Files if you are ready).","If you <strong>Cancel</strong>, confirm you are back in Session View."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What are the two export formats and their specs? <strong>Answer:</strong> WAV 48 kHz 16-bit; M4A 48 kHz 32-bit.","What do you tap after choosing a type? <strong>Answer:</strong> <strong>Export</strong>. Then a progress bar, then a preview.","What does <strong>Cancel</strong> on the preview do? <strong>Answer:</strong> Exits the preview and returns to Session View."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §10.2","Ableton Note.md §5.2","Note FAQ (import formats — contrast, not export)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Export one file to the preview stage. Note the format you chose. You will <strong>Share</strong> it in 11.1.5."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-1-3</code></em>"}]}],"minutes":8},{"id":"note-l11-1-4","title":"11.1.4 — Preview playhead starts at 0","blocks":[{"type":"step","title":"11.1.4 — Preview playhead starts at 0","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.1 — Export audio</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can use the export preview to hear the bounce, and you can mark the “playhead starts at 0” claim as unsourced."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"When the render finishes, Note shows an audio preview of the finished recording. You listen there, then <strong>Share</strong> or <strong>Cancel</strong>. That preview is the official last stop before the file leaves the app."},{"type":"prose","html":"{type:'gap'} The syllabus title cites an RN “fix culture” that the playhead starts at 0. The assigned Release Notes extract (through 2.0.1) and Manual §10.2 do not state that the preview playhead starts at 0. Do not teach a playhead-at-zero bug fix as a documented fact. Observe the preview on your version. If the playhead begins at the start of the bounce, write that as observation."},{"type":"prose","html":"What you <em>can</em> teach: the bounce is scenes top to bottom, so the preview should open on scene 1’s audio. If you arranged a quiet intro as scene 1, the preview starts there even if the hook is scene 2. That is arrangement, not a playhead bug."},{"type":"prose","html":"Record the Note version from <strong>Settings → Help</strong> next to any playhead observation."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Export a Set that has at least two scenes with different material.","When the preview appears, watch where playback begins. Write “starts at beginning / starts elsewhere” as observation.","Listen through the scene join. Confirm scene order matches the Session grid top to bottom.","Do not invent an RN citation for playhead position.","<strong>Share</strong> or <strong>Cancel</strong>.","Write the Note version beside the observation."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What do the extracts guarantee after a render? <strong>Answer:</strong> An audio preview of the finished recording, then <strong>Share</strong> or <strong>Cancel</strong>.","Is “playhead starts at 0” in the assigned RN/manual text? <strong>Answer:</strong> No. Treat it as a gap unless you are citing an extract we do not have.","Why might the preview start with something quiet? <strong>Answer:</strong> Scene 1 is first. Longest clip in that scene sets its length."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §10.2 (preview; Share; Cancel)","Note Release Notes extract (no playhead-at-0 line — gap)","Course syllabus <code>note-l11-1-4</code> title (not a product source)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Export once. Write three lines: version, where the preview began (observation), whether scene order matched the grid."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-1-4</code></em>"}]}],"minutes":8},{"id":"note-l11-1-5","title":"11.1.5 — Share bounce to other apps","blocks":[{"type":"step","title":"11.1.5 — Share bounce to other apps","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.1 — Export audio</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can tap <strong>Share</strong> on the export preview and send the WAV or M4A to Files, AirDrop, or another app."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"When you are ready, tap <strong>Share</strong> to bring up the device’s share menu. From there you save the exported file to your device or share it with other apps. Manual and Ableton Note.md name AirDrop, Messages, email, and more. This is iOS Share Sheet, not Ableton Cloud."},{"type":"prose","html":"The file is the bounce only. It does not include the Set, samples as separate assets, or macros. A collaborator who receives a WAV can listen or drop it on an audio track in any DAW. They cannot open it as a Note Set. For the Set, use <strong>Share To…</strong> (<code>.ablbundle</code>) or Cloud."},{"type":"prose","html":"<strong>Cancel</strong> leaves the preview without sharing. Export again if you cancelled and still need the file."},{"type":"prose","html":"Gate J requires an audio export completed. Saving to Files is enough evidence. You do not need to post the bounce publicly."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Export a Set that has clips. Wait for the preview.","Tap <strong>Share</strong>.","Choose <strong>Save to Files</strong> (or AirDrop to your Mac). Pick a folder you can find later.","Leave Note. Open Files and confirm the WAV or M4A is there.","Optionally AirDrop or Mail it to a second place. Confirm it is audio, not <code>.ablbundle</code>.","Return to Session View. Repeat <strong>Set Settings → Export Audio → Share</strong> from memory."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Where does <strong>Share</strong> appear? <strong>Answer:</strong> On the audio export preview, after the render.","What do you send? <strong>Answer:</strong> The WAV or M4A bounce, via the iOS share menu.","Can the recipient open that file as a Note Set? <strong>Answer:</strong> No. They need <code>.ablbundle</code> or Cloud for the Set."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §10.2","Ableton Note.md §5.2","Sharing Note Sets (Share To… is the Set path — contrast)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Save one bounce to Files. Write the filename, format, and folder. That is the Module 11.1 practice."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-1-5</code></em>"}]}],"minutes":8},{"id":"note-l11-1-6","title":"11.1.6 — When bounce beats Cloud (collaborators without Live)","blocks":[{"type":"step","title":"11.1.6 — When bounce beats Cloud (collaborators without Live)","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.1 — Export audio</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can pick a bounce when the other person only needs to hear the idea, and Cloud or <code>.ablbundle</code> when they need the Set."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Ableton Cloud syncs Note Sets to Live’s browser and to other Note/Move/Push devices on the same Ableton account. You cannot share your Cloud login as a collaboration method: Cloud Sets are only for the person signed in with that account (FAQ). Collaborators get <strong>Share To…</strong> (an <code>.ablbundle</code> they open in Note or Live 11.2.5+) or a bounce they can play anywhere."},{"type":"prose","html":"A bounce wins when the listener has no Live, no Note, or no interest in clips. Email a WAV/M4A. They hear scenes top to bottom. They cannot edit Drift. <strong>Share To…</strong> wins when they have Note or Live and should continue the sketch. Cloud wins when <em>you</em> are moving the Set to your own Live."},{"type":"prose","html":"Link Audio (2.0+, send only) is a live stream to Live/Push, not a file for someone offline."},{"type":"prose","html":"Do not put a collaborator’s work in your Cloud slot as a “share.” That is your eight-Set transfer tray, not a dropbox."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Write the recipient: “me in Live” / “friend with Note or Live” / “friend with neither.”","Match the path: Cloud or <code>.ablbundle</code> for the first two; <strong>Export Audio → Share</strong> for the third.","If the third case is real, export and send the bounce (AirDrop, Messages, Mail).","If they have Note or Live, use <strong>Share To…</strong> instead and say so.","Do not enable Cloud with their email on your phone as a shortcut. FAQ: same account only.","Keep both files if Gate J will need export <em>and</em> Cloud/Share."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Who can see your Cloud Sets? <strong>Answer:</strong> Only the Ableton account signed in on Note and Live. Not a collaborator’s different account.","When is a bounce the right send? <strong>Answer:</strong> When they need to hear the music and do not have (or need) Note or Live.","What file do you send when they will open the Set? <strong>Answer:</strong> <code>.ablbundle</code> via <strong>Share To…</strong>, or Cloud to your own Live."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note FAQ (Cloud same account; Share To… for collaborators; cannot share someone else’s Cloud)","Sharing Note Sets","Ableton Note Manual §10.1 and §10.2"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Name one real person and pick bounce vs <code>.ablbundle</code> vs Cloud in one sentence. Send that format, or write the sentence if you will not send today."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-1-6</code></em>"}]}],"minutes":8},{"id":"note-l11-1-7","title":"11.1.7 — export best scene arrangement","blocks":[{"type":"step","title":"11.1.7 — export best scene arrangement","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.1 — Export audio</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can rearrange scenes so the bounce plays in the order you mean, then export that grid."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"The bounce is not a secret Arrangement View. Note has no Arrangement View. Export records scenes from top to bottom. The longest clip in each scene sets that scene’s length. If scene 1 is an 8-bar drum loop and scene 2 is a 2-bar count-in you meant as an intro, the file will play the loop first and the count-in second."},{"type":"prose","html":"Long-press scenes to rearrange, duplicate, or delete (Session View). Max eight scenes. Build density on purpose: intro sparse, hook full, break thinner — Beatmaking’s chorus / verse / intro-outro, mapped onto scene rows. Empty clip slots in a scene do not pad time; the longest <em>clip</em> does. A one-bar hat loop next to an eight-bar pad makes an eight-bar scene."},{"type":"prose","html":"Listen to the preview before you <strong>Share</strong>. If the story is wrong, <strong>Cancel</strong>, reorder scenes, export again."},{"type":"prose","html":"This lab is the Module 11.1 practice: one audio export saved to Files, from a grid you arranged."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Open a Set with at least two scenes (add or duplicate if needed).","Long-press scene numbers and put the listening order top to bottom.","Check longest clips so a short hook is not swallowed by a leftover 16-bar pad in the same row unless you want that length.","<strong>Set Settings → Export Audio</strong>. Choose WAV or M4A. <strong>Export</strong>.","Listen to the preview. If the order is wrong, <strong>Cancel</strong>, fix scenes, export again.","<strong>Share</strong> to Files. Confirm the file."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What sets the order of the bounce? <strong>Answer:</strong> Scene order, top to bottom.","What sets each scene’s length in the file? <strong>Answer:</strong> The longest clip in that scene.","Can you export an Arrangement timeline Note does not have? <strong>Answer:</strong> No. Reorder scenes, then bounce."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §10.2 and §5.4","Ableton Note Manual (scenes: long-press rearrange; max 8)","Beatmaking with Ableton Note (chorus / verse / intro-outro; avoid only an 8-bar loop)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Export the best scene order you can make in ten minutes. Save the file to Files. That is the module practice."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-1-7</code></em>"}]}],"minutes":8}],"exercises":[]},{"id":"note-m-11-2-102","code":"11.2","title":"11.2","blurb":"11.2","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l11-2-1","title":"11.2.1 — Prerequisites checklist (version, account, network)","blocks":[{"type":"step","title":"11.2.1 — Prerequisites checklist (version, account, network)","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.2 — Cloud → Live hand-off (primary professional path)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can tick version, account, and network before you expect a Note Set to appear in Live."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Cloud hand-off fails for boring reasons. Collect them once:"},{"type":"list","items":["<strong>Live version.</strong> Note Sets and Cloud need Live 11.2.5 or later. All editions and licenses (Trial, Lite, Intro, Standard, Suite, Education) can open Note Sets at that version. Update Live if you are below it.","<strong>Same Ableton account email</strong> on Note and on the Live license / Live Cloud sign-in. A personal Gmail in Note and a work email on the Live serial will not show Sets.","<strong>Network.</strong> Note uploads or removes Cloud Sets only while the device has Wi-Fi or allowed mobile data. Uploads queue when you are offline and start when a connection returns (manual). Sync time depends on Set size and connection (seconds to minutes).","<strong>Cloud enabled</strong> in Note (toggle / library banner / Set Options <strong>Upload</strong>) and <strong>Show Cloud</strong> in Live’s Library settings."],"ordered":true},{"type":"prose","html":"Cloud holds eight Sets. It is transfer, not backup. Local copies stay under Files → On My iPhone/iPad → Ableton Note → Projects."},{"type":"prose","html":"Skip this checklist and you will debug the browser for an hour."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Write Live’s version (Live → About, or the installer you use). Mark ≥ 11.2.5 yes/no.","Write the email on your Ableton account / Live license.","In Note, confirm you will sign into Cloud with that same email.","Confirm Wi-Fi or Note’s Mobile Data is allowed.","Confirm you know the Note Cloud toggle and Live’s <strong>Show Cloud</strong>.","Keep this card next to the computer for 11.2.16 if something is missing later."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What Live version opens Note Sets and Cloud? <strong>Answer:</strong> 11.2.5 and later.","What email must match? <strong>Answer:</strong> The Ableton account used in Note Cloud and the account on the Live license / Live Cloud sign-in.","Can Note upload with all radios off? <strong>Answer:</strong> Not until a connection returns. Then queued uploads start."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Compatibility","Note FAQ (Cloud; versions; account)","Ableton Note Manual §2.1 (upload needs connection; queue)","Note Sets in Ableton Cloud not Appearing in Live (Steps 1–2)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Fill a five-line card: Live version, email, network yes/no, Note Cloud off/on, Live <strong>Show Cloud</strong> off/on. Fix any no before 11.2.4."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-2-1</code></em>"}]}],"minutes":8},{"id":"note-l11-2-2","title":"11.2.2 — Live ≥ 11.2.5","blocks":[{"type":"step","title":"11.2.2 — Live ≥ 11.2.5","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.2 — Cloud → Live hand-off (primary professional path)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can refuse to start a Cloud hand-off on a Live version below 11.2.5."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Note Sets can be opened in Ableton Live and are supported in Live 11.2.5 and later. Cloud is available in Live 11.2.5 and later. Shared <code>.ablbundle</code> files open in Live 11.2.5+. Using Note Presets in Live is the same floor. Compatibility points at “How to update Live” if you are behind."},{"type":"prose","html":"The floor is the <em>Live</em> version, not the edition. Lite 12 that ships with Note is new enough. An old Live 11.1 install on the studio Mac is not. Trial is allowed. Education is allowed."},{"type":"prose","html":"Note 1.1.1 fixed a metadata warning (“new file format version”) by re-saving Sets from updated Note. That is a Note-side save, not a reason to skip the 11.2.5 Live update."},{"type":"prose","html":"If you only export WAV/M4A, you do not need Live at all. Gate J does: open in Live + <strong>Collect All and Save</strong>. Get the version right now."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["On the computer, open Live and read the version (About Live).","If it is 11.2.5 or newer (including Live 12), mark pass.","If it is older, update Live using Ableton’s update guide before you enable Cloud.","Write edition (Trial / Lite / Intro / Standard / Suite / Education). Any of these is fine at 11.2.5+.","Do not install a second pirated copy. Use the license you own or the Lite serial from Note.","Keep the version number for the Gate J notes page."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What is the minimum Live version for Note Sets and Cloud? <strong>Answer:</strong> 11.2.5.","Does Lite count? <strong>Answer:</strong> Yes. All editions and licenses, including Trial and Education.","Does exporting audio require this version? <strong>Answer:</strong> No. Opening the Set in Live does."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Compatibility (11.2.5+; all editions)","Note FAQ (Cloud versions; what licenses work)","Using Note Presets in Live (11.2.5 and later)","Sharing Note Sets / Manual §3.3 (<code>.ablbundle</code> in Live 11.2.5+)","Note Release Notes 1.1.1 (metadata warning — contrast)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Write “Live x.x.x — OK / update required.” If update is required, do that before 11.2.4."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-2-2</code></em>"}]}],"minutes":8},{"id":"note-l11-2-3","title":"11.2.3 — Same Ableton account email as Live license","blocks":[{"type":"step","title":"11.2.3 — Same Ableton account email as Live license","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.2 — Cloud → Live hand-off (primary professional path)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can sign into Note Cloud with the email that owns the Live license so Sets appear in Live."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"When you enable Cloud in Note, sign in to Ableton.com using the email address associated with your Ableton Live license (FAQ). The troubleshooting article: the Ableton account used to enable Cloud in Note must match the account used to enable Cloud in Live, or synced Sets will not appear. Be sure to log in using the same email address."},{"type":"prose","html":"Two emails is the classic miss: Note on a phone Apple ID / old login, Live on the shop account. Re-enable Cloud on both sides with the main account (11.2.16 walks the click path)."},{"type":"prose","html":"Cloud Sets are only visible to that account. You cannot drop a Set into a collaborator’s Cloud. Use <strong>Share To…</strong> for them."},{"type":"prose","html":"An Ableton account is not required to <em>use</em> Note. It is required for Cloud."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Write the email on your Live license (ableton.com account, or the mail that received the serial).","In Note, if Cloud is already on, you will confirm that email in 11.2.4 / 11.2.16.","If you have two Ableton logins, pick the one that owns Live. Plan to sign both Note and Live into that one.","Do not create a third account “for the course.”","Write the chosen email on the prerequisites card.","Say the rule out loud: same email, both products."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Which email must Note Cloud use? <strong>Answer:</strong> The email associated with the Ableton Live license / the Live Cloud sign-in.","What happens if the emails differ? <strong>Answer:</strong> Synced Sets do not appear in Live.","Do you need an Ableton account to make music in Note? <strong>Answer:</strong> No. Only for Cloud."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note FAQ (sign in with the Live license email; account not required for Note itself)","Note Sets in Ableton Cloud not Appearing in Live (Step 2)","Note Compatibility (Ableton user account for Cloud)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Circle one email on paper. That is the only login you will use for Note Cloud and Live Cloud in this module."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-2-3</code></em>"}]}],"minutes":8},{"id":"note-l11-2-4","title":"11.2.4 — Enable Cloud in Note","blocks":[{"type":"step","title":"11.2.4 — Enable Cloud in Note","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.2 — Cloud → Live hand-off (primary professional path)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can turn on Ableton Cloud in Note and complete the browser login with the correct account."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"From Note’s <strong>App Settings</strong>, turn on <strong>Ableton Cloud</strong>. Enabling the toggle opens ableton.com in a web browser so you can connect the service to your Ableton User Account. You can also reach the same toggle from the Enable Ableton Cloud area in the Set Library, or via <strong>Upload to Ableton Cloud</strong> in Set Options."},{"type":"prose","html":"Log in with the Live-license email. After authorization, return to Note (the <strong>Open</strong> button in the troubleshooting flow). Sets already in Cloud — for example from Move — appear in the Ableton Cloud area of the library."},{"type":"prose","html":"Cloud holds eight Sets. Local files remain on the device. Turning Cloud on does not upload every Local Set. You still choose <strong>Upload</strong> per Set."},{"type":"prose","html":"If the browser lands on Enable Ableton Cloud while already logged into the wrong account, log out of ableton.com in that browser and log in with the right email (11.2.16)."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Open the Set Library. Tap the three dots (bottom left) → <strong>Ableton Cloud</strong>, or use the library banner.","Turn the <strong>Ableton Cloud</strong> toggle on.","In the browser, sign in with the Live-license email and grant access.","Return to Note. Confirm a Cloud section exists in the library (it may be empty).","Do not upload a Set yet if you only wanted the toggle (11.2.6 uploads).","Reopen <strong>App Settings</strong> from memory and confirm the toggle is on."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What does enabling the toggle open? <strong>Answer:</strong> ableton.com in a browser, to connect Cloud to your Ableton account.","Name three entry points. <strong>Answer:</strong> <strong>App Settings</strong> toggle, Set Library banner, Set Options → <strong>Upload to Ableton Cloud</strong>.","Does enabling Cloud upload all Local Sets? <strong>Answer:</strong> No. You upload chosen Sets. Capacity is eight."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §2.1","Note FAQ (How do I enable Ableton Cloud)","Note Sets in Ableton Cloud not Appearing in Live (Re-Enabling Cloud in Note)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Enable Cloud with the correct email. Screenshot the Cloud section of the library (empty is fine)."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-2-4</code></em>"}]}],"minutes":8},{"id":"note-l11-2-5","title":"11.2.5 — Show Cloud in Live Library settings","blocks":[{"type":"step","title":"11.2.5 — Show Cloud in Live Library settings","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.2 — Cloud → Live hand-off (primary professional path)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can turn on <strong>Show Cloud</strong> in Live’s Library settings and sign into the same account."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"To see synced Note Sets in Live, enable Cloud in Live as well as in Note. In Live, go to Settings (Preferences) → <strong>Library</strong> and turn on <strong>Show Cloud</strong>. A Cloud label appears in Places in the browser. Click it and sign in with the same Ableton account you used in Note."},{"type":"prose","html":"To hide Cloud in Live later, turn <strong>Show Cloud</strong> off. That is not the same as turning Cloud off in Note (Note → Settings → Ableton Cloud). Disabling Cloud on all iOS devices does not remove already-synced Sets from Live’s browser; only opting out via the Ableton account removes Cloud data (troubleshooting article)."},{"type":"prose","html":"If Cloud is shown but empty, do not assume Note failed. Sign-in mismatch and unfinished download are the next lessons."},{"type":"prose","html":"Live 11.2.5+ is still required."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Open Live 11.2.5 or later.","Open Settings → <strong>Library</strong>. Enable <strong>Show Cloud</strong>.","In the browser Places, select <strong>Cloud</strong>. Sign in if asked, same email as Note.","Confirm the Cloud section exists (Sets may arrive after upload/sync).","Write “Show Cloud on / signed in as [email].”","Do not turn <strong>Show Cloud</strong> off unless you are hiding the label on purpose."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Where is <strong>Show Cloud</strong>? <strong>Answer:</strong> Live Settings → <strong>Library</strong>.","What account do you use on the Cloud label? <strong>Answer:</strong> The same Ableton email as Note Cloud / the Live license.","Does hiding <strong>Show Cloud</strong> delete Note’s Cloud Sets? <strong>Answer:</strong> No. It hides the label in Live. Account opt-out is the full removal path."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note FAQ (Show Cloud; disable Cloud in Live)","Note Sets in Ableton Cloud not Appearing in Live (Step 2)","Ableton Note.md §5.1 (Preferences &gt; Library &gt; Show Cloud)","Troubleshooting Problems with Note Files (disabling iOS Cloud vs account opt-out)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Turn <strong>Show Cloud</strong> on and sign in. Screenshot Places with the Cloud label visible."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-2-5</code></em>"}]}],"minutes":8},{"id":"note-l11-2-6","title":"11.2.6 — Upload Set; wait for sync","blocks":[{"type":"step","title":"11.2.6 — Upload Set; wait for sync","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.2 — Cloud → Live hand-off (primary professional path)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can upload one Set to Cloud and wait until both Note and Live actually have it."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Tap the three dots next to a Set’s play button and select <strong>Upload to Ableton Cloud</strong>. The Set moves to the Ableton Cloud section of the library. It then appears in Live’s browser under Cloud in Places, and on other Note installs logged into the same email."},{"type":"prose","html":"Note needs a connection. If Wi-Fi and mobile data are off, the upload starts when a connection returns. File size and internet speed change the wait: a few seconds to a few minutes. Note can look finished after the <em>upload</em> while Live is still <em>downloading</em>. If the Cloud folder in Live does not match the phone, wait; see Ableton Cloud Upload Times (troubleshooting article)."},{"type":"prose","html":"Cloud holds eight Sets. Uploading a ninth means you rotate: remove one first (11.3.4). A ~100 MB sample warning exists; oversized samples can fail Cloud (RN 1.0.6)."},{"type":"prose","html":"Do not delete the Local-looking copy from Files. Cloud is not backup. The project also remains under Ableton Note → Projects."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Pick a small Set with clips (a 4-track sketch is fine). Confirm you have a Cloud slot.","Set Options (three dots) → <strong>Upload to Ableton Cloud</strong>.","Watch the Set appear under Cloud in Note’s library.","On the Mac, wait. Refresh your eyes on Live’s Cloud folder. Do not assume one spinner means both sides are done.","If nothing appears after a patient wait, go to 11.2.16 (account) before you re-upload forever.","Write start time and “visible in Live yes/no.”"],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["How do you upload a specific Set? <strong>Answer:</strong> Set Options (three dots) → <strong>Upload to Ableton Cloud</strong>.","Why might Note look done while Live is empty? <strong>Answer:</strong> Upload to Cloud can finish before download to Live finishes. Size and speed matter.","How many Sets can Cloud hold? <strong>Answer:</strong> Eight."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §10.1 and §2.1","Note FAQ (8 Sets; offline)","Troubleshooting Problems with Note Files (sync delay)","Note Sets in Ableton Cloud not Appearing in Live (Step 1, upload times)","Note Release Notes 1.0.6 (100 MB)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Upload one Set. Do not open it in Live until it is visible in the Cloud folder. Tick wait-complete on your card."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-2-6</code></em>"}]}],"minutes":8},{"id":"note-l11-2-7","title":"11.2.7 — Open from Live browser","blocks":[{"type":"step","title":"11.2.7 — Open from Live browser","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.2 — Cloud → Live hand-off (primary professional path)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can open the uploaded Note Set from Live’s Cloud folder as a Live Set."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Once uploaded, the Set is in Live’s browser under <strong>Cloud</strong> in Places. The folder is similar to a Live Project folder. You can access individual samples and recordings, or expand the <code>Set.abl</code> file to access individual tracks. You can also double-click the <code>.ablbundle</code> file to open it as a Live Set."},{"type":"prose","html":"Ableton Note.md: drag individual tracks or clips into an existing session, or double-click the <code>.ablbundle</code> to open the whole project as a new Live Set."},{"type":"prose","html":"Opening it makes a Live Set. That Live Set will not go back to Note (11.2.12). The next two lessons are verify contents, then <strong>Collect All and Save</strong> immediately so samples do not vanish if you later remove the Note Set from Cloud."},{"type":"prose","html":"Use Live 11.2.5+. Same account. If the folder is missing, do not open a random User Library preset and call it the hand-off."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["In Live, open Places → <strong>Cloud</strong>.","Find the folder named for your uploaded Set.","Double-click the <code>.ablbundle</code> (or open <code>Set.abl</code> as the manual describes) to open it as a Live Set.","Confirm Session View shows the Note tracks.","Do not save yet until you have 11.2.8–11.2.9 — or save only after Collect All and Save as taught there.","Write “opened in Live: yes/no.”"],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Where do you click? <strong>Answer:</strong> Live browser → Places → <strong>Cloud</strong> → the Set folder → <code>.ablbundle</code> (or <code>Set.abl</code> / contents).","What two open styles do the sources allow? <strong>Answer:</strong> Open the whole Set, or drag individual tracks/clips/samples into a session.","After it opens, is it still a Note Set? <strong>Answer:</strong> You are now in a Live Set. It will not return to Note."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §10.1","Ableton Note.md §5.1","Using Note Presets in Live (open from Cloud label)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Open the uploaded Set once. Leave it open for 11.2.8. Do not remove it from Cloud yet."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-2-7</code></em>"}]}],"minutes":8},{"id":"note-l11-2-8","title":"11.2.8 — Verify sounds, samples, effects present","blocks":[{"type":"step","title":"11.2.8 — Verify sounds, samples, effects present","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.2 — Cloud → Live hand-off (primary professional path)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can check that the Live Set still holds the Note instruments, samples, and effects before you archive it."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Note instruments and effects are compatible with Live when you import a Note Set. Open Device View (double-click a track header) and look: Drift, Drum Rack, Melodic Sampler, Wavetable, the two track audio effects, Main FX if you used them. Play the Session clips. Missing media after a Cloud remove or a disconnected User Library drive is a known failure (Troubleshooting Problems with Note Files). Verify <em>before</em> you delete the Cloud slot."},{"type":"prose","html":"Samples you recorded or imported in Note should be in the Cloud folder’s sample/recording areas and on the tracks. If a clip plays silence, do not assume the idea is gone — check missing-file warnings. Re-add the Set to Cloud from the iOS device if you already removed it, then <strong>Collect All and Save</strong> (next lesson)."},{"type":"prose","html":"Wavetable-from-Note in Lite/Intro/Standard appears as a locked rack: macros only. That is expected, not a missing device. Full Wavetable is Suite or a Pack."},{"type":"prose","html":"This check is the musical proof the hand-off worked."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["With the Set open in Live, play each track that had clips in Note.","Double-click track headers. Confirm devices and the two audio effects (and Main FX if used).","Trigger a user sample or environmental recording if the Set has one.","If a file is missing, stop. Use the troubleshooting order: Set still in Cloud, User Library drive connected, then Collect All and Save.","Write a tick list: drums / bass / harmony / lead / samples / FX.","Leave the Set unsaved-as-archive until 11.2.9 if you have not collected yet."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What should survive the open? <strong>Answer:</strong> Note instruments, their effects, and the samples/recordings used in the Set.","What does a locked Wavetable rack mean in Lite/Intro/Standard? <strong>Answer:</strong> Expected. Macros work; full Wavetable view does not.","Why verify before removing the Set from Cloud? <strong>Answer:</strong> Removing it can cause missing-file errors in Live until you re-add and collect."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note FAQ (instruments/effects compatible when importing a Note Set)","Ableton Note Manual §10.1","Using Note Presets in Live (locked rack)","Troubleshooting Problems with Note Files (missing files)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Play the Set in Live and tick devices + samples. Fix misses before you collect and save."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-2-8</code></em>"}]}],"minutes":8},{"id":"note-l11-2-9","title":"11.2.9 — Collect All and Save immediately","blocks":[{"type":"step","title":"11.2.9 — Collect All and Save immediately","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.2 — Cloud → Live hand-off (primary professional path)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can run <strong>Collect All and Save</strong> as soon as a Note Set is open in Live so samples stay on the computer."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"When you use Note content in Live — opening <code>.abl</code> / <code>.ablbundle</code> as a Live Set, or using individual samples — always use <strong>Collect All and Save</strong> from Live’s File menu. That command collects and saves all external files referenced by the current Set, so content is not lost if the Note Set is later removed from Cloud."},{"type":"prose","html":"FAQ: when opening a Note Set in Live for the first time, use <strong>Collect All and Save</strong> so files remain locally accessible to Live. Troubleshooting: if you already hit a missing-file error after removing the Note Set from Cloud, put it back on Cloud, reopen, then collect."},{"type":"prose","html":"This is the professional habit. Cloud is eight rotating slots, not an archive. The Live Project folder after Collect All and Save is the archive."},{"type":"prose","html":"Do it immediately. Do not arrange for an hour and then remove the Cloud Set first."},{"type":"prose","html":"Gate J requires this step by name. No substitute (Export WAV is not Collect All and Save)."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["With the Note-originated Set open in Live, go to Live’s <strong>File</strong> menu.","Choose <strong>Collect All and Save</strong>.","Pick a Live Project location on a drive that will stay connected (a missing external User Library drive is a known miss).","Confirm samples live in the Project folder.","Only then is it safe to rotate that Set out of Note’s eight Cloud slots.","Write “Collect All and Save: done” on the hand-off card."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What does <strong>Collect All and Save</strong> do? <strong>Answer:</strong> Collects and saves external files referenced by the Live Set into the Project folder.","When do you run it? <strong>Answer:</strong> Immediately, the first time you open the Note Set in Live.","What failure does it prevent? <strong>Answer:</strong> Missing samples after the original Note Set is removed from Cloud (or a disconnected library drive)."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §10.1","Note FAQ (Managing Files; Collect All and Save)","Troubleshooting Problems with Note Files"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Run <strong>Collect All and Save</strong> on the Set you opened in 11.2.7. Tick the module checkpoint: samples local, command done."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-2-9</code></em>"}]}],"minutes":8},{"id":"note-l11-2-10","title":"11.2.10 — Save Note devices as Live User Library presets","blocks":[{"type":"step","title":"11.2.10 — Save Note devices as Live User Library presets","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.2 — Cloud → Live hand-off (primary professional path)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can save a Note device from the opened Set into Live’s User Library."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Note presets can be saved for use in Live. Path from Using Note Presets in Live: share the Set via Cloud or <strong>Share To…</strong>; from the Cloud label, open the Set; double-click a track header to open Device View; use the <strong>Save Preset</strong> button to add the device to your User Library. It then appears in Live’s Browser → User Library."},{"type":"prose","html":"FAQ: once you have opened the Note Set in Live, you can save any Note preset as a Live preset. The other direction is not free-form: only specifically created presets can be exported from Live and transferred to Note (Presets on Move &amp; Note). Do not expect to design a random Live rack and send it back."},{"type":"prose","html":"Wavetable from Note in Lite/Intro/Standard stays a locked rack: macros only. Saving that preset saves the locked rack. In Suite (or with the Pack), you get the full device."},{"type":"prose","html":"Save after Collect All and Save so the preset’s samples have a local home."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Open the Note Set in Live (Cloud or <code>.ablbundle</code>). <strong>Collect All and Save</strong> if you have not.","Double-click a track header (a Drift or Drum Rack you like).","Click <strong>Save Preset</strong>.","In the browser, open User Library and find the new preset.","Load it on an empty Live track to confirm.","Repeat for one more device if you want a small palette."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Where do you save the preset? <strong>Answer:</strong> Device View → <strong>Save Preset</strong> → User Library.","Can you send any Live preset back to Note? <strong>Answer:</strong> No. Only specifically created presets transfer to Note. See Presets on Move &amp; Note.","What happens to Wavetable in Live Standard? <strong>Answer:</strong> Locked rack. Macros from Note remain; full Wavetable view does not."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Using Note Presets in Live","Note FAQ (How do I access Note presets in Live; Live→Note limits)","Ableton Note Manual §10.1 (one-way Sets)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Save one Note device as a User Library preset. Write its name. That preset is now a Live tool, not a Note file."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-2-10</code></em>"}]}],"minutes":8},{"id":"note-l11-2-11","title":"11.2.11 — Expand parameters in Live beyond Note surface","blocks":[{"type":"step","title":"11.2.11 — Expand parameters in Live beyond Note surface","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.2 — Cloud → Live hand-off (primary professional path)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can say what Live can open that Note’s surface hid, and what stays locked in some editions."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Note Track Presets expose a subset of parameters (macros and the device pages Note shows). In Live you open Device View on the same devices. Drift can be expanded in Live; Note 1.5 also lets you access/purchase full Drift from a Drift icon in Device View on the phone. Wavetable in Suite or with the Pack shows the full device; in Lite, Intro, or Standard the Note Wavetable preset is a locked rack — Note’s shown controls remain, the rest do not appear."},{"type":"prose","html":"That is the sourced expansion story. {type:'gap'} Do not invent a list of hidden Live-only knobs per factory preset. Open the device and see. Do not claim Suite-only devices as owned on Note."},{"type":"prose","html":"Live also has Arrangement View, which Note does not. Expanding “beyond Note” includes arranging scenes into a timeline after Collect All and Save — a Live skill, not a Note button. Sets still do not travel back."},{"type":"prose","html":"Use this lesson to plan what you will do in Live, not to pretend Note grew extra pages."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["In the opened Note Set, double-click a Drift track. Look at Device View versus the macros you had in Note.","Double-click a Wavetable track if you have one. Write locked rack vs full device based on your Live edition.","Save any sound you care about as a User Library preset (11.2.10).","Do not try to re-upload the Live Set to Note.","Write two lines: “I can now … in Live” and “I still cannot … (return to Note / MPE in Note / etc.).”","Keep those lines for 11.4.6."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What is a locked Wavetable rack? <strong>Answer:</strong> In Lite/Intro/Standard, only the controls shown in Note stay editable. Full Wavetable is Suite/Pack.","Does opening in Live add Arrangement View to Note? <strong>Answer:</strong> No. Arrangement is in Live. Note stays Session.","Can you send the expanded Live Set back? <strong>Answer:</strong> No."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Using Note Presets in Live (locked rack vs Suite)","Note FAQ (presets; Live→Note)","Note Release Notes 1.5 (full Drift purchase path on Note)","Ableton Note Manual §10.1 (one-way)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Open two devices in Live. Write locked vs expandable for each. That is the expansion literacy check."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-2-11</code></em>"}]}],"minutes":8},{"id":"note-l11-2-12","title":"11.2.12 — Why Live Set cannot return to Note","blocks":[{"type":"step","title":"11.2.12 — Why Live Set cannot return to Note","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.2 — Cloud → Live hand-off (primary professional path)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can state the one-way rule and plan the sketch as if Live is a finish room, not a round trip."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Sharing Sets between Note and Live works in one direction: Note Sets open in Live, not the other way around. FAQ: it is not possible to transfer Sets from Live into Note. Once a Note Set is imported into Live and saved as a Live Set, the modified version can no longer be opened in Note. Compatibility: Sets created or saved in Live cannot be opened in Note."},{"type":"prose","html":"Cloud is Note → Live / Note / Move / Push, not back. There is no “download this Live Project to the phone as a Set.” If you need the sketch on the phone after Live work, you still have the original Note Set locally (and in Cloud until you rotate it). That original does not include Live arrangement, new Live devices, or edits you made after the save."},{"type":"prose","html":"Treat Live as downstream. Finish ideas in Note first (Beatmaking: don’t fine-tune forever; 80/20). Then hand off. Duplicate the Note Set before a risky Live experiment if you want a clean mobile copy."},{"type":"prose","html":"This is why Gate J records both the Note export and the Live Collect All and Save: two artifacts, one direction."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Say the rule out loud: Note → Live, never Live → Note.","Confirm your original Set still exists in Note (Local or Cloud) after you saved in Live.","Make one small edit in Live (a clip move). Confirm you cannot upload that Live Set to Note.","If you still need a phone sketch, open the <em>Note</em> original, not the Live Project.","Write this on the process notes page you will use for Gate J.","Do not search Settings for a reverse toggle. There isn’t one in the extracts."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Can a Live Set be opened in Note? <strong>Answer:</strong> No.","What happens after you save the imported Set as a Live Set? <strong>Answer:</strong> That modified version can no longer be opened in Note.","Where is the mobile copy after hand-off? <strong>Answer:</strong> Still on the device under Ableton Note → Projects, and in Cloud if you have not removed it."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §10.1","Note FAQ (Can I transfer Sets from Live to Note; Can I transfer Live Sets back)","Note Compatibility"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Write one sentence you would tell a collaborator who asks you to “send the Live Set back to Note.” Keep it."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-2-12</code></em>"}]}],"minutes":8},{"id":"note-l11-2-13","title":"11.2.13 — alternate path without Cloud","blocks":[{"type":"step","title":"11.2.13 — alternate path without Cloud","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.2 — Cloud → Live hand-off (primary professional path)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can hand a Set to Live or another Note install with <strong>Share To…</strong> when Cloud is off or the wrong tool."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"<strong>Share To…</strong> packages the Set as an <code>.ablbundle</code> (Set + samples + metadata). From the home screen, Set Options → <strong>Share To…</strong> → pick AirDrop, Files, Messages, and so on. Open the file in Note or in Live 11.2.5+. FAQ: you can transfer without Cloud using <strong>Share To…</strong> or AirDrop. Collaborators should use this path instead of your Cloud login."},{"type":"prose","html":"On a Mac, AirDrop the bundle and double-click it in Live. If you Share To the same folder many times, macOS can append a number after the extension or strip <code>.ablbundle</code> — then Live cannot open the file. Rename to restore <code>.ablbundle</code>, or share to a new folder (Troubleshooting Problems with Note Files)."},{"type":"prose","html":"Cloud is still the primary professional path for <em>your</em> Live browser. <code>.ablbundle</code> is the backup, the collaborator send, and the no-account path. Gate J allows Cloud <strong>or</strong> Share To."},{"type":"prose","html":"Collect All and Save after you open the bundle in Live. Same rule."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["In the Set Library, tap Set Options → <strong>Share To…</strong>.","Save to Files or AirDrop to the Mac.","Confirm the filename ends in <code>.ablbundle</code> (no extra number after the extension).","On the Mac, open the bundle in Live 11.2.5+ (or in Note on another iOS device).","<strong>Collect All and Save</strong> if this is your working Live copy.","Write “bundle path used: yes” as an alternate to Cloud."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What is inside an <code>.ablbundle</code>? <strong>Answer:</strong> The Set, its samples, and metadata.","Who should use Share To instead of Cloud? <strong>Answer:</strong> Collaborators (different account), and you when Cloud is off or full.","What macOS rename bug should you check? <strong>Answer:</strong> A number appended after the extension, or a missing <code>.ablbundle</code> when the name already ended in a number."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Sharing Note Sets","Ableton Note Manual §3.3 and §10.1","Note FAQ (transfer without Cloud)","Troubleshooting Problems with Note Files (Share To naming)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Create one <code>.ablbundle</code> on Files or via AirDrop. Confirm the extension. You now have a Cloud-free hand-off."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-2-13</code></em>"}]}],"minutes":8},{"id":"note-l11-2-14","title":"11.2.14 — Live Lite activation path for Note buyers","blocks":[{"type":"step","title":"11.2.14 — Live Lite activation path for Note buyers","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.2 — Cloud → Live hand-off (primary professional path)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can claim the Live 12 Lite serial that ships with Note and register it if you do not already own Live."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Note comes with a free Live 12 Lite license if you do not already own Ableton Live. In Note, go to <strong>Settings</strong> and tap <strong>Get Ableton Live Lite</strong>. You receive a Lite 12 serial to register in your Ableton account. Then download and authorize Live 12 Lite."},{"type":"prose","html":"Manual §2.8: every purchase of Note includes Live Lite via this option. FAQ: Note is not included with a Live license — you still buy Note in the App Store — but Lite is included with Note. If you already own a higher edition, you do not need Lite to open Note Sets. All editions at 11.2.5+ open them."},{"type":"prose","html":"Use the same Ableton email you will use for Cloud. Registering Lite on a different email recreates the 11.2.3 mismatch."},{"type":"prose","html":"Lite is enough for Gate J: open the Set, Collect All and Save, save presets (Wavetable may be a locked rack). You do not need Suite for the capstone."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["If you already run Live 11.2.5+ or Live 12 (any edition), write “Lite not required” and skip the claim.","If not, open Note <strong>App Settings → Get Ableton Live Lite</strong>.","Register the serial on ableton.com with the Cloud email.","Download Live 12 Lite and authorize it.","Confirm the version is ≥ 11.2.5 (Lite 12 is).","Turn <strong>Show Cloud</strong> on in that Live (11.2.5)."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Where do you claim Lite? <strong>Answer:</strong> Note <strong>Settings → Get Ableton Live Lite</strong>.","Do you need Lite if you already own Live 12 Standard? <strong>Answer:</strong> No. That edition already opens Note Sets.","Is Note free with a Live license? <strong>Answer:</strong> No. Note is a separate App Store purchase."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note FAQ (What kind of Live license; How do I activate Lite)","Ableton Note Manual §2.8","Note Release Notes 1.1 (Live 12 Lite for Note users)","Note Compatibility (all editions)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Either claim and authorize Lite, or write the Live edition you already own. You need one authorized Live for the rest of 11.2."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-2-14</code></em>"}]}],"minutes":8},{"id":"note-l11-2-15","title":"11.2.15 — All Live editions open Note Sets (Trial→Suite)","blocks":[{"type":"step","title":"11.2.15 — All Live editions open Note Sets (Trial→Suite)","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.2 — Cloud → Live hand-off (primary professional path)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can name every Live edition and license that opens a Note Set, and you can refuse Suite-only myths."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"All Live editions, including Lite, Intro, Standard, and Suite, and all licenses, including Trial and Education, are compatible with Note Sets (Compatibility). FAQ repeats the list: Trial, Lite, Intro, Standard, Suite, and Education. Cloud works with the same list. The floor is version 11.2.5, not the paid tier."},{"type":"prose","html":"What <em>does</em> change by edition is the device interior. Wavetable from a Note preset is a locked rack in Lite, Intro, and Standard; full Wavetable is Suite or a Pack. That is not “the Set will not open.” The Set opens. Some panels stay closed."},{"type":"prose","html":"Do not tell a Lite user they must upgrade to finish Gate J. Collect All and Save, samples, clips, Drift, Drum Rack, Sampler, effects, and macros are the hand-off. Suite is a later expansion, not a Note compatibility key."},{"type":"prose","html":"Trial is explicitly included. A time-limited Trial at 11.2.5+ is a legal Gate J Live."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Write your edition and license type.","Write the Compatibility list from memory: Trial, Lite, Intro, Standard, Suite, Education.","Open your Note Set in that Live. Confirm it loads.","If you use Wavetable, note locked vs full. Do not treat locked as a failed open.","Tick Gate J item “Opened in Live” regardless of edition.","Do not claim Suite-only devices as Note-owned."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Which editions open Note Sets? <strong>Answer:</strong> All of them listed: Trial, Lite, Intro, Standard, Suite, Education, at Live 11.2.5+.","Does Cloud require Standard or Suite? <strong>Answer:</strong> No. Same list.","What is edition-dependent after the Set opens? <strong>Answer:</strong> Full vs locked view of Suite-only devices such as Wavetable."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Compatibility","Note FAQ (What Live licenses work; Cloud minimum license)","Using Note Presets in Live"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Write “My Live: [edition] [version] — opens Note Sets: yes.” Keep it on the Gate J notes page."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-2-15</code></em>"}]}],"minutes":8},{"id":"note-l11-2-16","title":"11.2.16 — Troubleshooting: Cloud missing / wrong account","blocks":[{"type":"step","title":"11.2.16 — Troubleshooting: Cloud missing / wrong account","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.2 — Cloud → Live hand-off (primary professional path)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can walk the official four-step Cloud-missing procedure instead of reinstalling Note."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"If synced Sets are not under Cloud in Live, the Knowledge Base order is:"},{"type":"list","items":["<strong>Internet.</strong> Note uploads or removes Sets only on Wi-Fi or allowed mobile data. Confirm both. Upload time varies with size and connection.","<strong>Cloud on in both apps, same email.</strong> Enable Cloud in Note and <strong>Show Cloud</strong> in Live. The accounts must match.","<strong>Re-enable with the same account.</strong> In Note, toggle Ableton Cloud off and on (browser opens). If you are already logged in, go to ableton.com from that page, log out, then enable again and log in with the main email. Return via <strong>Open</strong>. In Live, right-click the Cloud label → <strong>Sign Out</strong>, then Sign In from Places → Cloud, and repeat the browser logout/login if the wrong account auto-fills. Return via <strong>Return to Application</strong>.","<strong>Server status.</strong> Check the Ableton Status Page for a Cloud outage."],"ordered":true},{"type":"prose","html":"Do not skip to “delete the app” (backup the Ableton Note folder first if you ever do). Wrong email is more common than a corrupt Set."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Confirm Wi-Fi or Note Mobile Data. Retry the upload.","Confirm Note Cloud on and Live <strong>Show Cloud</strong> on.","If still empty, run the Note off/on + browser logout/login with the Live-license email.","Sign out/in on Live’s Cloud label the same way.","If both sides are correct and still empty, check Ableton Status.","Write which step fixed it, or “still failing after 1–4.”"],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What is the most common account failure? <strong>Answer:</strong> Different emails on Note Cloud and Live Cloud / the Live license.","How do you force Note to re-auth? <strong>Answer:</strong> Toggle Ableton Cloud off and on, then log in in the browser with the correct email.","What is step 4 if the account is correct? <strong>Answer:</strong> Ableton Status Page (possible Cloud outage)."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Sets in Ableton Cloud not Appearing in Live (Steps 1–4)","Note FAQ (My sets aren’t showing up)","Note FAQ (Can I turn off Cloud)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"If Cloud already works, write “not needed” and still copy the four steps onto your card. If it fails, run them in order and stop when Sets appear."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-2-16</code></em>"}]}],"minutes":8},{"id":"note-l11-2-17","title":"11.2.17 — Presets Move/Note special export rules (KB pointer)","blocks":[{"type":"step","title":"11.2.17 — Presets Move/Note special export rules (KB pointer)","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.2 — Cloud → Live hand-off (primary professional path)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can point at the official Presets on Move &amp; Note rule instead of inventing a Live→Note export recipe."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Once a Note Set is open in Live, you can save any Note preset as a Live User Library preset (11.2.10). The reverse is restricted. FAQ: only specifically created presets can be exported from Live and transferred to Note. Learn more about presets on Move &amp; Note. Using Note Presets in Live: to transfer presets from Live to Note, use the Presets on Move guide."},{"type":"prose","html":"{type:'gap'} The assigned extracts do not reprint those Move/Note export rules. Do not invent folder names, rack limits, or “flatten then drag” steps. Open the Knowledge Base articles the FAQ names: Presets on Move &amp; Note, and the Presets on Move guide."},{"type":"prose","html":"Sets remain one-way. A Live Set is not a Note Set. A saved Live preset is not automatically a Note Track Preset."},{"type":"prose","html":"Appendix A in this course exists for Move as a peer. This lesson is the pointer, not a second Move manual."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Review what you <em>can</em> do: save Note devices into Live’s User Library.","Write the reverse rule: only specifically created presets go Live → Note.","Open the KB articles named above if you need the Move/Note procedure. Follow those pages, not this paragraph.","Do not try to export a random Live Set into Note to “test.”","If you do not use Move, you still need the rule so you do not promise a round trip.","Keep the KB titles on your hand-off card."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Can every Live preset be sent to Note? <strong>Answer:</strong> No. Only specifically created presets.","Where are the detailed rules? <strong>Answer:</strong> Presets on Move &amp; Note, and the Presets on Move guide (KB). Not fully in these extracts.","Does saving a Note preset in Live create a path back for the whole Set? <strong>Answer:</strong> No. Sets stay one-way."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note FAQ (Can I use presets from Note in Live? How about Live in Note?)","Using Note Presets in Live (Presets on Move guide pointer)","Ableton Note Manual §10.1 (Sets one-way)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Write the one-sentence reverse-preset rule and the two KB titles. Do not add unsourced steps."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-2-17</code></em>"}]}],"minutes":8},{"id":"note-l11-2-18","title":"11.2.18 — full hand-off of a 4-track sketch","blocks":[{"type":"step","title":"11.2.18 — full hand-off of a 4-track sketch","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.2 — Cloud → Live hand-off (primary professional path)</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can take one 4-track Note sketch through Cloud or <code>.ablbundle</code> into Live and finish with <strong>Collect All and Save</strong>."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"This is the module lab. Syllabus practice: Live opens the Set with samples; Collect All and Save done. Checkpoint: hand-off checklist ticked."},{"type":"prose","html":"Use a Set with at least four tracks (drums, bass, harmony, lead or FX is the Gate J shape; for this lab, four tracks with clips is enough). Prerequisites: Live ≥ 11.2.5, same email, network, Cloud on both sides <strong>or</strong> a clean <code>.ablbundle</code>. Upload or Share. Wait for sync if Cloud. Open from Live’s Cloud folder or double-click the bundle. Play. Verify devices and samples. <strong>Collect All and Save</strong> immediately. Optionally save one device as a User Library preset."},{"type":"prose","html":"Do not add extra deliverables. No stems, no video, no Suite-only bounce. If Cloud fails, use <code>.ablbundle</code>. If Live is missing, you cannot complete this lab or Gate J — claim Lite (11.2.14)."},{"type":"prose","html":"Keep the Note original on the phone. The Live Project is the downstream copy."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Choose a 4-track Set with clips. Note the name.","Upload to Cloud <strong>or</strong> <strong>Share To…</strong> an <code>.ablbundle</code>.","Open it in Live 11.2.5+. Play all four tracks.","Verify samples and effects. Fix misses (11.2.8 / 11.2.16) before you continue.","<strong>File → Collect All and Save</strong>.","Tick the checklist: version, account, opened, sounds present, collected. Write the Live Project path."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What two artifacts prove the lab? <strong>Answer:</strong> The Set open in Live with sounds, and a completed <strong>Collect All and Save</strong>.","What if Cloud will not show the Set? <strong>Answer:</strong> Use <code>.ablbundle</code>, or run 11.2.16, then collect.","Must this lab include a public bounce? <strong>Answer:</strong> No. Export is Module 11.1 / Gate J, not an extra 11.2 deliverable."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §10.1","Note FAQ (Cloud; Collect All and Save)","Sharing Note Sets","Course syllabus Module 11.2 practice and checkpoint"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Complete the hand-off once. The ticked card is the Module 11.2 deliverable."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-2-18</code></em>"}]}],"minutes":8}],"exercises":[]},{"id":"note-m-11-3-103","code":"11.3","title":"11.3","blurb":"11.3","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l11-3-1","title":"11.3.1 — Daily 10–20 minute sketch ritual","blocks":[{"type":"step","title":"11.3.1 — Daily 10–20 minute sketch ritual","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.3 — Mobile production operating system</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can run a short daily sketch using Beatmaking’s start rules, without treating 10–20 minutes as an Ableton spec."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Beatmaking with Ableton Note: start with a title, a prompt, a limitation, or an intention; take a breath; capture the idea; do not fine-tune until you decide it is worth continuing (80/20 — the main parts come quickly). Put space between making and judging. Store raw ideas."},{"type":"prose","html":"{type:'gap'} Ableton does not define a 10–20 minute session. That length is this course’s ritual, not a Note setting. Use it as a container so you stop mixing. Session plan in Level 0.4 already asked for a time limit. Auto-save every ~10–15 seconds means a short session is still on disk."},{"type":"prose","html":"Note is a sketchbook: Session grid, max 8 tracks / 8 scenes / 16-bar clips. A daily pass can be one drum loop and a bass. You do not owe Cloud or Export every day. You owe a named Set and a decision later (11.3.10)."},{"type":"prose","html":"Wired headphones if you are playing pads (FAQ latency). Orange mic icon is expected."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Write a title or prompt (Beatmaking examples: a wild title, “write about a city”).","Set a timer for a short block (the course suggests 10–20 minutes). State one intention.","<strong>+ New</strong>. Capture drums or a melody first. Do not open the mixer as the first act.","When the timer ends, name the Set, optional artwork, leave it Local.","Do not judge the loop today. Close Note.","Repeat tomorrow. Five sessions is the module practice."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What official pedagogy starts a sketch? <strong>Answer:</strong> Title, prompt, limitation, intention (Beatmaking). Record first; fine-tune later.","Is 10–20 minutes a Note specification? <strong>Answer:</strong> No. It is a course container.","Must you upload every daily Set to Cloud? <strong>Answer:</strong> No. Cloud has eight slots and is not backup."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Beatmaking with Ableton Note","Note FAQ (auto-save; Cloud not backup; Bluetooth headphones)","Course syllabus Module 11.3 practice (one-week calendar, 5 sessions)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Run one timed sketch now. Write title, intention, and stop time. Do not mix it."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-3-1</code></em>"}]}],"minutes":8},{"id":"note-l11-3-2","title":"11.3.2 — Naming convention for Sets","blocks":[{"type":"step","title":"11.3.2 — Naming convention for Sets","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.3 — Mobile production operating system</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can rename a Set with a working title you will still understand next week."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Set Options lets you rename a Set. Beatmaking: a title in mind gives you the sound and the instruments — “Meta Balloons,” “Dinosaur Torpedo.” Level 0.4 already used working titles to constrain a sketch. That is the sourced naming idea: a title that means something to you, not a default “Set.”"},{"type":"prose","html":"{type:'gap'} Ableton does not publish a required filename scheme (no official <code>YYYYMMDD-key-bpm</code> rule in the extracts). {type:'gap'} Illegal Cloud characters are mentioned in earlier syllabus lines; the assigned extracts here do not list the character set. If Cloud rejects a name, change it and retry. Do not invent the illegal list."},{"type":"prose","html":"A name is not artwork and not Cloud. Duplicate before a destructive rename experiment if you need the old label. <code>.ablbundle</code> files inherit the Set name (<code>MySong.ablbundle</code>); keep the name clean before Share To so macOS does not fight an already-numeric suffix (11.2.13)."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Open Set Options on a recent sketch.","Rename it to a working title you can say aloud (Beatmaking style), not “Set 3.”","If you also want a date for <em>your</em> archive, add it — as your habit, not as a Note requirement.","Upload or Share only after the name is stable.","Write three names you will reuse as a pattern (for example title-only; title + mood).","Rename one more Set from memory."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Where do you rename? <strong>Answer:</strong> Set Options (three dots next to the Set).","What official advice exists about titles? <strong>Answer:</strong> Beatmaking: a title directs sound and instruments. Note lets you rename.","Is there an official Note naming syntax in the extracts? <strong>Answer:</strong> No. Do not treat a course pattern as a product rule."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §3.3 (rename)","Beatmaking with Ableton Note (song title)","Sharing Note Sets / Troubleshooting (<code>.ablbundle</code> names)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Rename two Local Sets with working titles you will recognize in a week."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-3-2</code></em>"}]}],"minutes":8},{"id":"note-l11-3-3","title":"11.3.3 — Artwork as memory aid","blocks":[{"type":"step","title":"11.3.3 — Artwork as memory aid","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.3 — Mobile production operating system</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can set Set artwork from Photos or the camera so the library reminds you what the sketch felt like."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Set Options: choose artwork from your Photo Library, or take a photo. That is the whole product control. Widgets / home-screen artwork behavior exists in the wider course; here you only need the Set picture."},{"type":"prose","html":"Beatmaking: store raw ideas; give time before you judge; organize folders (good / park / ugly). A still photo of the room, a color, or an object tied to the title is a memory hook when the library is twenty tiles of similar drums. That pairing is pedagogy, not an Ableton “artwork = recall” spec."},{"type":"prose","html":"Artwork is not a bounce and not Cloud metadata you should rely on as backup. It travels with the Set you see in the library. Duplicate a Set if you want a variant with different art."},{"type":"prose","html":"Take the photo in the same session as the sketch if you want the memory to be true."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Open Set Options on a named sketch.","Add artwork from Photo Library or take a photo now.","Return to the library. Confirm you can find the Set by the picture alone.","Repeat on one older Set you keep forgetting.","Do not spend the session designing a cover. One shot.","Write which Set you can now spot without reading the name."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Where does artwork come from? <strong>Answer:</strong> Photo Library or the camera, via Set Options.","Is artwork a Cloud backup? <strong>Answer:</strong> No. Cloud is transfer of Sets, not an archive strategy.","Why take the photo in the same hour as the sketch? <strong>Answer:</strong> Beatmaking’s memory of the idea is fresh; the tile will match the feeling you had."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §3.3","Beatmaking with Ableton Note (store, organize, delay before judge)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Put artwork on three Sets you still care about. Close Note and reopen the library. Find them by picture."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-3-3</code></em>"}]}],"minutes":8},{"id":"note-l11-3-4","title":"11.3.4 — Cloud rotation: which 8 earn slots","blocks":[{"type":"step","title":"11.3.4 — Cloud rotation: which 8 earn slots","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.3 — Mobile production operating system</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can treat Cloud’s eight slots as a transfer tray and rotate only Sets that are going to Live, Move, Push, or another Note device."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"You can sync a total of eight Sets. Older Note had five; 1.2 raised the cap to eight. Cloud is designed to share and sync across devices, not as file backup. Local copies remain under Files → On My iPhone/iPad → Ableton Note → Projects. Removing a Set from Cloud can break Live sessions that were not collected (11.2.9)."},{"type":"prose","html":"Slots are expensive. They earn a place if you will open the Set in Live this week, or you need it on another logged-in device. Daily sketches stay Local until one survives a week (11.3.10). Collaborators do not get a slot on your account; they get <code>.ablbundle</code>."},{"type":"prose","html":"When you need a ninth, remove one from Cloud <em>after</em> Collect All and Save if Live used it, or after you no longer need the cross-device copy. Disabling Cloud on iOS does not wipe Live’s already-synced Cloud label."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Count Sets in Note’s Cloud section. Write n / 8.","For each, write why it is there: Live this week / other device / leftover.","Pick leftovers. Confirm Live has Collect All and Save if you opened them.","Remove a leftover from Cloud to free a slot (only after that check).","Upload one Set that actually needs transfer.","Recheck the count."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["How many Sets does Cloud hold? <strong>Answer:</strong> Eight.","What does not belong in those eight by default? <strong>Answer:</strong> Every daily sketch, and anything that is only a personal archive (use Files / Share To).","What must you do before removing a Set Live still references? <strong>Answer:</strong> <strong>Collect All and Save</strong> in that Live Set, or expect missing files."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note FAQ (8 Sets; Cloud not backup; local Projects path)","Ableton Note Manual §2.1","Note Release Notes 1.2 (8, was 5)","Troubleshooting Problems with Note Files"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Write your current eight (or fewer) and one Set you will evict next. Do the eviction only if Live is safe."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-3-4</code></em>"}]}],"minutes":8},{"id":"note-l11-3-5","title":"11.3.5 — Local archive via Share/Files weekly","blocks":[{"type":"step","title":"11.3.5 — Local archive via Share/Files weekly","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.3 — Mobile production operating system</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"You can build a weekly <code>.ablbundle</code> archive in Files because Cloud is not backup."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"FAQ: Cloud is not a file backup or storage system. Before you delete Note, back up the entire Ableton Note folder or individual Projects via <strong>Share To…</strong>, or back up the iOS device. Sets live in Files → On My iPhone/iPad → Ableton Note. <strong>Share To…</strong> writes <code>Name.ablbundle</code> you can Save to Files, AirDrop, or another app."},{"type":"prose","html":"A weekly pass is course practice, not an Ableton schedule. Beatmaking: keep raw ideas in a folder. Your Files folder is that folder. Do not rely on the eight Cloud tiles."},{"type":"prose","html":"Same Share To naming caution: do not dump twenty copies into one Mac folder and lose <code>.ablbundle</code> extensions. Use dated subfolders if you share to a computer often."},{"type":"prose","html":"This archive is how you delete a bad Local Set without fear, and how you survive a phone swap."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["In Files, create or open a folder you will treat as the Note archive.","In Note, <strong>Share To…</strong> each Set you still care about that is not already in that folder this week.","Save to Files (or AirDrop to a Mac folder).","Confirm each file ends in <code>.ablbundle</code> and opens (or at least is present).","Optionally export a WAV of the one Set you might send to a non-Live listener.","Write the date and the count of bundles."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Why weekly Share/Files if Cloud exists? <strong>Answer:</strong> Cloud holds eight and is not backup. Bundles and the Ableton Note folder are the archive.","What file type is the archive unit? <strong>Answer:</strong> <code>.ablbundle</code>.","What should you do before deleting the Note app? <strong>Answer:</strong> Back up the entire Ableton Note folder or the Projects via Share To / device backup."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note FAQ (Managing Files; Cloud not backup; Share To)","Sharing Note Sets","Ableton Note Manual §3.3","Troubleshooting Problems with Note Files (Share To naming)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Archive every Set you would be sad to lose. Write the folder path and today’s count."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-3-5</code></em>"}]}],"minutes":8},{"id":"note-l11-3-6","title":"11.3.6 — Scene form templates library","blocks":[{"type":"step","title":"11.3.6 — Scene form templates library","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.3 — Mobile production operating system</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Keep a short written library of scene forms you actually use, grounded in Note’s eight-scene limit and the Beatmaking section list."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"FAQ: a Set has at most <strong>eight scenes</strong>. Manual §4.3: a scene is a horizontal row; tap the scene number to launch all clips in that row."},{"type":"prose","html":"Beatmaking with Ableton Note names sections you can map onto those rows: <strong>chorus/hook</strong>, <strong>verse</strong> (sparser), <strong>intro/outro</strong>. It does not name “Break.” {type:'gap'} Do not invent a Break template as official Note vocabulary."},{"type":"prose","html":"A “template” here is a paper or Notes-app list, not a hidden Note file type. Example forms that stay inside eight rows:"},{"type":"list","items":["1 intro / 2 verse / 3 hook / 4 verse / 5 hook","1 loop / 2 add hats / 3 add stab (sparse-to-full, Manual scenes)","Demo-style 2.x: audio loop scene vs half-tempo scene (RN 2.0.1)"],"ordered":false}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Write three scene forms on paper, each ≤ 8 rows, using only hook / verse / intro / outro / density change.","In a Set, show scene numbers (Manual §4.3). Duplicate a scene (long-press) to build form B.","Launch form A top to bottom. Export later uses this order (Manual §10.2).","Save the paper list as your “form library.”","Recite: eight scenes; export is top to bottom; section names come from Beatmaking, not a Note menu."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["How many scenes can a Set have? <strong>Answer:</strong> Eight.","Does Note ship scene-form presets named Verse/Chorus? <strong>Answer:</strong> No. You assign rows. Beatmaking supplies the words.","What order does Export Audio use? <strong>Answer:</strong> All scenes, top to bottom; longest clip in a scene sets that scene’s length (Manual §10.2)."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note FAQ (max 8 scenes)","Ableton Note Manual §4.3, §10.2","Beatmaking with Ableton Note (chorus, verse, intro/outro)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Pick one form for the capstone. Write it at the top of your process notes before Gate J."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-3-6</code></em>"}]}],"minutes":8},{"id":"note-l11-3-7","title":"11.3.7 — From infinite loop to sectioned sketch checklist","blocks":[{"type":"step","title":"11.3.7 — From infinite loop to sectioned sketch checklist","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.3 — Mobile production operating system</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Turn one 8-bar loop into at least three scenes so the sketch has form, not an endless clip."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Beatmaking: “You’ll probably want to avoid only having an amazing 8 bar loop that spins endlessly.” Start there, then add intro/verse/hook."},{"type":"prose","html":"Note tools you already have:"},{"type":"list","items":["<strong>Duplicate Clip</strong> to the next slot (Manual §6.1) — variation factory.","<strong>Duplicate scene</strong> (long-press scene number, §4.3).","Sparse vs full: leave slots empty in the verse row; fill the hook row.","Clip ceiling <strong>16 bars</strong> (FAQ). Form is scenes, not one giant clip."],"ordered":false},{"type":"prose","html":"80/20 in Beatmaking: do not fine-tune forever before you decide the idea is worth sections."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Capture one 4- or 8-bar four-track loop (drums, bass, harmony, lead or FX).","Duplicate the scene. Mute or delete hats on the copy (verse).","Duplicate again. Add a stab or reverse (hook).","Launch 1 → 2 → 3. If it still feels like one loop, change density, not just volume.","Tick: three scenes, different density, still ≤ 8."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Why not one 16-bar clip for the whole song? <strong>Answer:</strong> 16 bars is the clip ceiling, and Beatmaking wants sections. Scenes are the form.","What official control copies a whole row? <strong>Answer:</strong> Long-press scene number → Duplicate.","What is “sparse vs full” here? <strong>Answer:</strong> Empty slots in one scene, filled slots in another."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Beatmaking with Ableton Note (endless loop; sections; 80/20)","Ableton Note Manual §4.3, §6.1","Note FAQ (16 bars, 8 scenes)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Keep this three-scene Set. It is the skeleton for Gate J (syllabus: ≥ 3 scenes with density differences)."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-3-7</code></em>"}]}],"minutes":8},{"id":"note-l11-3-8","title":"11.3.8 — Screen recording for process notes","blocks":[{"type":"step","title":"11.3.8 — Screen recording for process notes","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.3 — Mobile production operating system</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Record a Note session with <strong>Show Touches</strong> on, using iOS Control Center screen recording."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"KB <em>How to Create a Screen Recording in Note</em>: add Screen Recording to Control Center (Apple’s “Record the screen on your iPhone/iPad”). Enable access within apps. In Note, enable <strong>Show Touches</strong> so taps are visible. Then open Control Center from inside Note and record."},{"type":"prose","html":"Manual §2.4.5.1: Show Touches adds a small white circle that follows your gestures — for performance videos and tutorials."},{"type":"prose","html":"Syllabus Gate J wants one-page process notes with verbs (setup, capture, edit, sample, automate, send) plus the Note version. The video is evidence; the page is the deliverable. You can still submit without video if recording is blocked; {type:'gap'} Ableton does not require a video for Cloud. This lesson is the official recording path."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["iOS Settings: add <strong>Screen Recording</strong> to Control Center. Allow in-app access.","Note <strong>Preferences</strong>: <strong>Show Touches</strong> on.","Open Control Center from Note. Start recording. Capture 60 seconds of Capture → scene launch.","Stop. Watch the video: the white circle should match your taps.","Write five verbs + version on paper. That page is what Gate J lists."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Why enable Show Touches? <strong>Answer:</strong> So taps are visible in the recording (KB + Manual §2.4.5.1).","Where do you start the recording? <strong>Answer:</strong> iOS Control Center, from inside Note.","Is the video the Gate J deliverable? <strong>Answer:</strong> The syllabus lists process notes and version, not a mandatory video. The video supports the notes."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["How to Create a Screen Recording in Note (Ableton KB)","Ableton Note Manual §2.4.5.1 Show Touches","Course syllabus Module 11.4 (process notes)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Store the clip in Photos. Name it with the Set title + version. Do not upload it to Cloud."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-3-8</code></em>"}]}],"minutes":8},{"id":"note-l11-3-9","title":"11.3.9 — When to stop sketching and open Live","blocks":[{"type":"step","title":"11.3.9 — When to stop sketching and open Live","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.3 — Mobile production operating system</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Name the official hand-off: Note sketches; Live finishes. Stop when you need a Live-only job."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Manual §1: Note sketches, captures, samples, and <strong>sends</strong> Sets to Live, Move, Push, or another Note. Compatibility KB: Sets created or saved in Live <strong>cannot</strong> be opened in Note. Cloud is one-way."},{"type":"prose","html":"Official Live-only jobs (do not pretend Note has them):"},{"type":"list","items":["Arrangement View (Note is Session only — Manual §4).","Full Wavetable device view (locked rack in Standard — Using Note Presets in Live).","MIDI file I/O, AUv3, pitch bend (FAQ).","Two-way Cloud (FAQ)."],"ordered":false},{"type":"prose","html":"Beatmaking: separate creation from judgment; 80/20 — do not fine-tune forever. When the sketch has clips, scenes, and a send path, open Live (Lite ships with Note — FAQ / Manual §2.8)."},{"type":"prose","html":"Sister course <strong>Mastering Ableton Live 12</strong> owns the finish. This lesson is the stop rule."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["List what your current Set still needs (mix bus, arrangement, plugins).","Cross out anything Note cannot do (list above).","If the leftover is Live-only, export or Cloud now (Collect All and Save on first open — Manual §10.1).","If the leftover is another Note clip, stay in Note.","Recite: Note → Live is one way. Arrangement is a Live job."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Can you bring the Live Set back? <strong>Answer:</strong> No (FAQ / Compatibility).","What must you do in Live after opening a Note Set? <strong>Answer:</strong> Collect All and Save (Manual §10.1).","What is a valid reason to stay in Note? <strong>Answer:</strong> You still need Capture, scenes, or samples Note can do."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §1, §4, §10.1","Note FAQ; Note Compatibility KB","Using Note Presets in Live","Beatmaking with Ableton Note (80/20; delay judgment)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Write one sentence: “I will open Live when ___.” Put it on the Gate J notes page."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-3-9</code></em>"}]}],"minutes":8},{"id":"note-l11-3-10","title":"11.3.10 — Idea triage: good / park / delete after a week","blocks":[{"type":"step","title":"11.3.10 — Idea triage: good / park / delete after a week","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.3 — Mobile production operating system</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"After a delay, sort Sets into keep, park (Share/Files), or delete — without treating Cloud as backup."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Beatmaking: store raw ideas; give space before you judge; listen later (“a week or a month”); organize folders (The Good, The Bad, The Ugly); keep what stays memorable."},{"type":"prose","html":"Note facts that constrain triage:"},{"type":"list","items":["Cloud = <strong>8 Sets</strong>, transfer not backup (FAQ).","Auto-save every 10–15 seconds (FAQ). Local files: <strong>Files → On My iPhone/iPad → Ableton Note</strong>.","<strong>Share To…</strong> writes <code>.ablbundle</code> (Sharing Note Sets KB).","Delete only after a backup exists (Level 1). Cloud removal does not delete the local copy automatically (FAQ)."],"ordered":false},{"type":"prose","html":"“Park” = Share To Files or AirDrop, then free a Cloud slot. “Delete” = local delete after the bundle exists."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Wait at least a week after the last capture (Beatmaking).","Listen once. Label: <strong>good</strong> (stays Cloud or Local hero), <strong>park</strong> (bundle to Files), <strong>delete</strong> (only if parked or worthless).","For park: Set Options → <strong>Share To…</strong> → Files. Confirm the <code>.ablbundle</code>.","If it was in Cloud and you need the slot, remove it from Cloud after the local/park copy exists.","Recite: eight Cloud slots; park is Share To; Cloud is not the archive."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Why wait a week? <strong>Answer:</strong> Beatmaking: separate creation from judgment.","How many Sets does Cloud hold? <strong>Answer:</strong> Eight.","What file do you park? <strong>Answer:</strong> An <code>.ablbundle</code>."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Beatmaking with Ableton Note (delay; organize; memorable)","Note FAQ (8 Sets; auto-save; Cloud not backup)","Sharing Note Sets KB"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Triage five old Sets today. You should end with ≤ 8 Cloud Sets and a Files folder of parked bundles."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-3-10</code></em>"}]}],"minutes":8},{"id":"note-l11-3-11","title":"11.3.11 — Travel kit: wired headphones, MIDI, offline plans","blocks":[{"type":"step","title":"11.3.11 — Travel kit: wired headphones, MIDI, offline plans","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.3 — Mobile production operating system</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Pack a Note travel kit from documented constraints: latency, MIDI class-compliance, and Cloud’s need for a network."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Official constraints, not gadget taste:"},{"type":"list","items":["<strong>Wired headphones.</strong> Bluetooth latency 34–200 ms; wired 5–10 ms (Bluetooth Headphones and Latency in Note). FAQ recommends wired for playing instruments.","<strong>Class-compliant MIDI</strong> over USB or Bluetooth (Note MIDI Input KB). Powered USB hub if the controller draws too much. Pitch bend / MPE / sustain are <strong>not</strong> recorded.","<strong>Cloud needs a connection.</strong> Manual §2.1: uploads wait until Wi-Fi or cellular is available. You can disable cellular (Manual §1.1) and stay local.","<strong>Offline sketch is complete Note:</strong> Capture, scenes, samples, Share To later. Ableton account is not required to use the app (FAQ) — only for Cloud.","Screen stays awake in foreground (RN 1.0.15). Orange mic icon is expected (FAQ)."],"ordered":false}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Pack: device, <strong>wired</strong> headphones or adapter, optional class-compliant controller + cable/hub.","In iOS Settings → Note, set <strong>Cellular Data</strong> off if you do not want Cloud on LTE.","On a plane/train: make a Set locally. Do not wait for Cloud.","When you have Wi-Fi, Upload or Share To.","Recite: wired for timing; MIDI is class-compliant; Cloud can wait."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Why wired headphones? <strong>Answer:</strong> Bluetooth adds 34–200 ms (KB). FAQ recommends wired.","Can you sketch without an Ableton account? <strong>Answer:</strong> Yes. Account is for Cloud (FAQ).","What MIDI types will not arrive? <strong>Answer:</strong> MPE, pitch-bend, sustain (MIDI Input KB)."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Bluetooth Headphones and Latency in Note","Note FAQ (wired rec; account; orange mic)","Note MIDI Input KB","Ableton Note Manual §1.1, §2.1","Note Release Notes 1.0.15 (screen awake)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Photograph the kit. Add “cellular off / Cloud later” to the compatibility card from Level 0."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-3-11</code></em>"}]}],"minutes":8}],"exercises":[]},{"id":"note-m-11-4-104","code":"11.4","title":"11.4","blurb":"11.4","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l11-4-1","title":"11.4.1 — Capstone brief reading","blocks":[{"type":"step","title":"11.4.1 — Capstone brief reading","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.4 — Capstone + Gate J</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Read the official Gate J list and copy it onto a process page with your Note version."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"The syllabus capstone (Module 11.4) is the brief. It is self-assessment. The desktop academy cannot watch Note."},{"type":"prose","html":"<strong>Gate J deliverables (syllabus):</strong>"},{"type":"list","items":["Note Set with <strong>≥ 4 tracks</strong> (drums, bass, harmony, lead or FX)","<strong>≥ 3 scenes</strong> with intentional density differences","Clips originated via <strong>Capture</strong> (Fixed <strong>and</strong> Free used at least once)","MIDI Editor polish (timing and velocity intentional)","<strong>≥ 1</strong> user/environmental or imported sample","<strong>≥ 1</strong> captured automation","Key &amp; Scale used intentionally on melodic material","Audio <strong>export</strong> completed","<strong>Cloud upload or Share To</strong> completed","Opened in <strong>Live</strong> + <strong>Collect All and Save</strong>","One-page process notes (verbs: setup, capture, edit, sample, automate, send)","<strong>Version number</strong> of Note recorded on the notes page"],"ordered":true},{"type":"prose","html":"Every line maps to a sourced lesson. If you lack 2.x audio tracks, a Sampler/Drum Rack sample still satisfies (5). Do not add Suite-only stems."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Open <strong>Help</strong>. Write the version at the top of a new page.","Copy the 12 lines. Leave a checkbox by each.","Open the Set you will use. Count tracks and scenes against (1) and (2).","Circle the first gap. Tomorrow’s lessons are 11.4.2–11.4.5.","Recite: 12 lines, self-scored, version on the page."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Who grades Gate J? <strong>Answer:</strong> You. No auto-grader.","Must you use Cloud? <strong>Answer:</strong> Cloud <strong>or</strong> Share To (line 9).","What Live command is mandatory on first open? <strong>Answer:</strong> Collect All and Save (Manual §10.1)."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Course syllabus Module 11.4 (capstone table)","Ableton Note Manual §10.1","Note FAQ (limits that make 4 tracks / 3 scenes legal)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Do not build today. Only read and copy the brief. Building starts 11.4.2."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-4-1</code></em>"}]}],"minutes":8},{"id":"note-l11-4-2","title":"11.4.2 — Build: Capture day","blocks":[{"type":"step","title":"11.4.2 — Build: Capture day","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.4 — Capstone + Gate J</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"On the capstone Set, use <strong>Fixed Length</strong> and <strong>Free Length</strong> Capture at least once each."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Capture in Note / Manual §8.1:"},{"type":"list","items":["<strong>Fixed Length:</strong> add a clip at 1/2/4/8/16 bars, play, <strong>Add</strong> commits notes.","<strong>Free Length:</strong> play without a clip, then <strong>Capture</strong> (stopped, up to eight bars) or <strong>Create Clip</strong> (transport running; new clip at least as long as the shortest existing clip).","First capture with transport stopped sets tempo.","Overdub: transport running + <strong>Add</strong>."],"ordered":false},{"type":"prose","html":"Gate J line 3 requires both Fixed and Free in the process, not necessarily on the same track. Stay inside 8 tracks / 16 bars."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Open the capstone Set. Enable the metronome if you want a click (empty 2.0.1 Sets do not auto-enable it — RN).","On drums, add a 2-bar clip (Fixed). Play. <strong>Add</strong>.","On bass or lead, play freely with transport stopped, then <strong>Capture</strong> (Free).","If tempo jumped, that is the first-capture rule. Set tempo manually if you needed a number first.","Tick Gate J line 3."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What is Fixed Length? <strong>Answer:</strong> Clip length chosen first (1/2/4/8/16), then play, then Add.","What is Free Length with transport stopped? <strong>Answer:</strong> Play up to eight bars, then Capture.","What sets tempo on the first stopped capture? <strong>Answer:</strong> Your performance (Manual §8.1.1–8.1.2 / FAQ)."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §8.1","Capture in Note KB","Note FAQ (tempo extract; limits)","Note Release Notes 2.0.1 (empty-set metronome)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Do not design sounds today. Capture only. Sound day is 11.4.3."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-4-2</code></em>"}]}],"minutes":8},{"id":"note-l11-4-3","title":"11.4.3 — Build: sound and FX day","blocks":[{"type":"step","title":"11.4.3 — Build: sound and FX day","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.4 — Capstone + Gate J</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Satisfy Gate J lines 5–7: one sample, one automation, Key &amp; Scale used on purpose."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"<strong>Sample (line 5):</strong> record into Drum Rack or Sampler, or import WAV/AIFF/M4A/MP3 (Working with Samples). 2.x audio tracks also count if Help shows 2.0.1+. Stay under 100 MB (RN 1.0.6)."},{"type":"prose","html":"<strong>Automation (line 6):</strong> transport running; dotted line; <strong>Add</strong> (Manual §7.5). One knob is enough."},{"type":"prose","html":"<strong>Key &amp; Scale (line 7):</strong> In Key + root + scale on melodic material (Manual §5.3). Greyed if no melodic instrument exists — add one."},{"type":"prose","html":"Track Preset still = instrument + two FX. Do not start a Live mix."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Add or import one sample. Play it in a clip.","Enable <strong>In Key</strong>. Play the harmony or lead. Confirm out-of-scale pads are gone.","Press Play. Automate one filter, macro, or FX knob. <strong>Add</strong>.","Tick Gate J lines 5, 6, and 7.","Recite the three lines you just closed."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Does a factory kit sample count? <strong>Answer:</strong> The brief says “user/environmental or imported.” Prefer a sample you recorded or imported.","Must automation be on every track? <strong>Answer:</strong> No. ≥ 1 captured automation.","What if In Key is greyed? <strong>Answer:</strong> No melodic instrument in the Set (Manual §5.3). Add one."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Course syllabus 11.4","Working with Samples in Note","Ableton Note Manual §5.3, §7.5","Note Release Notes 1.0.6"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Write on the process page: sample name, automated parameter, key/scale. That is the evidence."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-4-3</code></em>"}]}],"minutes":8},{"id":"note-l11-4-4","title":"11.4.4 — Build: scenes day","blocks":[{"type":"step","title":"11.4.4 — Build: scenes day","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.4 — Capstone + Gate J</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Reach ≥ 3 scenes with different density, and ≥ 4 tracks in role (drums, bass, harmony, lead or FX)."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Manual §4.3: scenes are rows; launch the number; max eight; long-press duplicate/delete/reorder. Show scene numbers."},{"type":"prose","html":"Gate J: four roles, three scenes, density differences. Use 11.3.7: verse sparse, hook full, intro thinner. Beatmaking section names apply."},{"type":"prose","html":"MIDI Editor polish (line 4) can happen today: tap preview, nudge/quantize/velocity (Manual §8.2). Intentional timing, not perfection."},{"type":"prose","html":"Export later plays scenes <strong>top to bottom</strong> (Manual §10.2). Put intro at the top if you want it first in the WAV."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Confirm four tracks with roles you can name.","Show scene numbers. Build or duplicate to <strong>at least three</strong> rows.","Thin scene 1, fill scene 2, change scene 3 (add/remove a clip).","Open MIDI Editor on one clip. Fix one obvious timing or velocity issue.","Launch 1-2-3. Tick Gate J lines 1, 2, and 4."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["How do you launch a whole row? <strong>Answer:</strong> Tap the scene number.","What makes density “intentional”? <strong>Answer:</strong> Different clips present or absent between rows — not random mutes you forgot.","What order will the export hear? <strong>Answer:</strong> Top scene to bottom."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Course syllabus 11.4","Ableton Note Manual §4.3, §8.2, §10.2","Beatmaking with Ableton Note"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Write scene names on paper (Intro / Verse / Hook). Note has no scene-title field. {type:'gap'}"},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-4-4</code></em>"}]}],"minutes":8},{"id":"note-l11-4-5","title":"11.4.5 — Transfer day","blocks":[{"type":"step","title":"11.4.5 — Transfer day","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.4 — Capstone + Gate J</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Complete Gate J lines 8–10: export audio, Cloud or Share To, open in Live, Collect All and Save."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"<strong>Export (line 8):</strong> Set Settings → <strong>Export Audio</strong>. WAV 48 kHz 16-bit or M4A 48 kHz 32-bit. Scenes top to bottom; longest clip in a scene sets length. Greyed if no clips (Manual §5.4 / §10.2)."},{"type":"prose","html":"<strong>Send (line 9):</strong> Upload to Cloud (8 slots, same Ableton email, Live 11.2.5+) <strong>or</strong> Share To… <code>.ablbundle</code> (Sharing Note Sets KB)."},{"type":"prose","html":"<strong>Live (line 10):</strong> Open the Set. <strong>File → Collect All and Save</strong> so samples survive if Cloud later drops the Note Set (Manual §10.1). One-way: you cannot bring the Live Set back (FAQ)."},{"type":"prose","html":"If Cloud is missing in Live: same account, Show Cloud, Live version — <em>Note Sets in Cloud not Appearing</em> KB."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Export WAV or M4A. Preview, then Share/save.","Either Upload to Cloud or Share To Files/AirDrop. Confirm the bundle or Cloud tile.","On the computer, open the Set in Live 11.2.5+.","Collect All and Save.","Tick Gate J lines 8, 9, and 10."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What sample rates/bit depths does Note export? <strong>Answer:</strong> WAV 48 kHz 16-bit or M4A 48 kHz 32-bit (Manual §10.2).","Why Collect All and Save? <strong>Answer:</strong> So Live keeps samples if the Note Set leaves Cloud.","Can you open the saved Live Set in Note tomorrow? <strong>Answer:</strong> No."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §5.4, §10.1, §10.2","Sharing Note Sets KB","Note FAQ; Cloud-not-appearing KB","Note Compatibility (Live 11.2.5+)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Put the WAV, the <code>.ablbundle</code> or Cloud name, and the Live project path on the process page."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-4-5</code></em>"}]}],"minutes":8},{"id":"note-l11-4-6","title":"11.4.6 — Live expansion plan (what you will do next in the Ableton course)","blocks":[{"type":"step","title":"11.4.6 — Live expansion plan (what you will do next in the Ableton course)","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.4 — Capstone + Gate J</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Write a short Live-only plan so the Note Set does not pretend to be a finished Live record."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Sister-course boundary (syllabus): full Live lives in <strong>Mastering Ableton Live 12</strong>. Note’s honest leftover jobs:"},{"type":"list","items":["Arrangement View (Note has Session only).","Deep devices / unlocked Wavetable (KB locked rack in Standard).","Mixing beyond track faders + two FX + Main FX.","Plugins / Max for Live — not in Note (no AUv3, FAQ)."],"ordered":false},{"type":"prose","html":"Using Note Presets in Live: save a Note device to User Library after Collect All and Save if you want the sound in other Live Sets."},{"type":"prose","html":"Do not list Suite Stem Separation. This studio’s Live edition is Standard (recovery plan / sister-course honesty)."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["After Collect All and Save, look at the Live Set.","Write three bullets that are <strong>Live-only</strong> (arrangement, mix, a Live device).","Write three bullets you already finished in Note (Capture, scenes, sample).","If a Wavetable track is locked, write “macros only in Standard.”","Keep the six bullets on the Gate J page."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Why not finish the song in Note? <strong>Answer:</strong> No Arrangement View; one-way Cloud; device/mix limits (Manual / FAQ).","What happens to Wavetable in Live Standard? <strong>Answer:</strong> Locked rack — shown controls only (KB).","Where do you learn Arrangement? <strong>Answer:</strong> The Ableton Live 12 course, not this one."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Course syllabus sister-course table","Ableton Note Manual §4 (Session), §10.1","Using Note Presets in Live","Note FAQ (AUv3; one-way)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Title the list “Live next.” Do not start those jobs in this lesson. Gate J is the Note package."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-4-6</code></em>"}]}],"minutes":8},{"id":"note-l11-4-7","title":"11.4.7 — Critique rubric: limits used creatively?","blocks":[{"type":"step","title":"11.4.7 — Critique rubric: limits used creatively?","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.4 — Capstone + Gate J</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Score the capstone against Note’s documented limits instead of against a fantasy mobile Live."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Official limits (FAQ / Manual): <strong>8 tracks</strong>, <strong>8 scenes</strong>, <strong>16-bar clips</strong>, <strong>8 Cloud Sets</strong>, no MIDI files, no AUv3, no pitch bend, no Live→Note, sampler transpose couples speed."},{"type":"prose","html":"Creative use means you <em>chose</em> inside those walls: scenes as form (not one loop), Capture instead of MIDI import, Share To for collaborators (FAQ: Cloud is same-account only), wired phones for timing."},{"type":"prose","html":"Beatmaking 80/20 and memorable-after-a-week are the musical half of the rubric."},{"type":"prose","html":"Rubric (self-score 0/1 each):"},{"type":"list","items":["Limits named on the notes page","Form uses ≥ 3 scenes because of the 16-bar ceiling","At least one limit changed a musical decision (example: no MIDI file → Capture)","No invented Android / two-way Cloud / AUv3 claim in the notes"],"ordered":false}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Read your process page and the Set.","Tick the four rubric lines.","Write one sentence: “The 8-scene / 16-bar limit made me ___.”","If you cannot finish that sentence, add a scene or shorten a clip, then retry.","Recite the four official numeric limits."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What are the four numeric limits? <strong>Answer:</strong> 8 tracks, 8 scenes, 16-bar clips, 8 Cloud Sets.","Is “I needed more tracks” a fail? <strong>Answer:</strong> No. Layering inside 8 is the point. Wanting Live’s unlimited tracks is a hand-off, not a Note fail.","Does Cloud for a friend count? <strong>Answer:</strong> No. Same-account only. Use Share To (FAQ)."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note FAQ (limits; Cloud account; Share To)","Ableton Note Manual (Session / clips / Cloud)","Beatmaking with Ableton Note"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Leave the four ticks on the Gate J page. 11.4.8 is the final review."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-4-7</code></em>"}]}],"minutes":8},{"id":"note-l11-4-8","title":"11.4.8 — Gate J review","blocks":[{"type":"step","title":"11.4.8 — Gate J review","blocks":[{"type":"prose","html":"<em>Level 11 · Module 11.4 — Capstone + Gate J</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Tick all twelve Gate J lines with evidence. If a line is open, do not call the gate passed."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Re-read 11.4.1’s twelve lines. This lesson is the checklist, not new features."},{"type":"prose","html":"Evidence, not vibes:"},{"type":"list","items":["Tracks/scenes: count in Session.","Capture both modes: you did 11.4.2.","Editor: one clip you touched.","Sample / automation / key: 11.4.3.","Export file exists.","Cloud tile or <code>.ablbundle</code> exists.","Live Set with Collect All and Save done.","Process page has verbs + <strong>version from Help</strong>."],"ordered":false},{"type":"prose","html":"If 2.x audio was optional, say so. If Cloud failed, Share To still closes line 9. If Live is not installed yet, claim Lite from <strong>Get Ableton Live Lite</strong> (FAQ / Manual §2.8) before you tick line 10."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Open Help. Confirm the version on the page still matches.","Walk the 12 lines. Tick only what you can point at.","For any open line, write the lesson number that closes it (do not invent a workaround).","Sign the page (your name, date). That is Gate J.","Recite: twelve lines, evidence, no grader."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Can you pass with Share To and no Cloud? <strong>Answer:</strong> Yes. Line 9 is Cloud <strong>or</strong> Share To.","Can you pass without opening Live? <strong>Answer:</strong> No. Line 10 is explicit.","What if Lite is unclaimed? <strong>Answer:</strong> Settings → Get Ableton Live Lite (Manual §2.8 / FAQ), then open the Set."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Course syllabus Module 11.4","Ableton Note Manual §2.8, §10","Note FAQ (Lite; Cloud or Share)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Photograph the ticked page next to the Session view. Archive both with the Set."},{"type":"prose","html":"<em>Syllabus ID: <code>note-l11-4-8</code></em>"}]}],"minutes":8}],"exercises":[]}]};
